for (const field of [
	"googleId",
	"facebookId",
	"openidId",
	"samlId",
	"ldapId",
	"githubId",
	"discordId",
	"appleId"
]) {
	if (field === "openidId") {
		userSchema.index({
			openidId: 1,
			openidIssuer: 1,
			tenantId: 1
		}, {
			unique: true,
			partialFilterExpression: { openidId: { $exists: true } }
		});
		continue;
	}
	userSchema.index({
		[field]: 1,
		tenantId: 1
	}, {
		unique: true,
		partialFilterExpression: { [field]: { $exists: true } }
	});
}
